def _short(date, level, paras):
    old = EN[date]["passage"]
    pics = [{k: p[k] for k in ("photo", "scene") if k in p} for p in old]
    pics = [x for x in pics if x]
    new = []
    for i, (t, k) in enumerate(paras):
        d = {"text": t, "ko": k}
        if i > 0 and pics: d.update(pics.pop(0))
        new.append(d)
    EN[date]["passage"] = new; EN[date]["level"] = level

